/** 四种轴向推进掠食者共享躯干、颌与尾柄架构，细节按物种分派。 */
function buildPredator(kind, body, motions) {
  const c = PREDATORS[kind];
  const torso = add(
    body,
    `${kind}_torso`,
    () => {
      const bodyLoft = loft(c.profile, c, {
        rings: 52,
        sides: 34,
        cut: true,
      });
      // 剑鱼扁平剑吻与躯干同一几何，截面椭圆扁、约占全长三分之一。
      if (kind !== "swordfish") return bodyLoft;
      const bill = loft(
        [
          [-0.66, 0.0035, 0.0016, -0.012],
          [-0.59, 0.009, 0.003, -0.011],
          [-0.51, 0.016, 0.0055, -0.009],
          [-0.43, 0.024, 0.009, -0.006],
          [-0.36, 0.033, 0.014, -0.003],
          [-0.3, 0.047, 0.033, 0],
        ],
        { back: "#2c3e56", belly: "#8fa2b2" },
        { rings: 22, sides: 14 },
      );
      return merge([bodyLoft, bill]);
    },
    SURFACE,
  );
  const swimming = bindAxialMotion(torso, motions, {
    axis: "y",
    amplitude: c.amp,
    frequency: c.freq,
  });
  swimming.name = `${kind}_continuous_body`;
  eyes(body, kind, c.eye, c.iris);
  if (kind === "ichthyosaur")
    add(
      body,
      `${kind}_sclerotic_rings`,
      () =>
        merge(
          [-1, 1].map((side) => {
            const ring = new THREE.TorusGeometry(0.029, 0.004, 6, 20);
            ring.rotateY(Math.PI / 2);
            ring.translate(side * 0.0675, c.eye[1], c.eye[2]);
            return paint(ring, "#586568");
          }),
        ),
      SURFACE,
    );
  const jaw = new THREE.Group();
  jaw.name = `${kind}_jaw`;
  jaw.position.set(0, c.roof, c.hinge);
  body.add(jaw);
  add(
    jaw,
    `${kind}_mandible`,
    () => {
      const profile = [];
      for (let i = 0; i <= 12; i++) {
        const t = i / 12,
          z = THREE.MathUtils.lerp(c.front, c.hinge + 0.025, t),
          [rx] = sampleSection(c.profile, z);
        // 旋齿鲨下颌在齿旋处加深成软骨囊，前缘薄、联合部厚。
        const ry = c.jawPouch
          ? THREE.MathUtils.lerp(
              (c.jawRy || 0.013) * 0.5,
              c.jawRy,
              THREE.MathUtils.smoothstep(t, 0.1, 0.8),
            )
          : c.jawRy || 0.013;
        profile.push([
          z,
          rx *
            THREE.MathUtils.lerp(
              0.18,
              0.86,
              THREE.MathUtils.smoothstep(t, 0, 0.18),
            ),
          ry *
            THREE.MathUtils.lerp(
              0.35,
              1,
              THREE.MathUtils.smoothstep(t, 0, 0.16),
            ),
          c.roof -
            c.gap * (1 - THREE.MathUtils.smoothstep(t, 0.55, 1)) -
            0.009 -
            (c.jawPouch ? 0.012 * Math.exp(-(((t - 0.42) / 0.3) ** 2)) : 0),
        ]);
      }
      return loft(profile, c, { jaw: true, rings: 28, sides: 24 }).translate(
        0,
        -c.roof,
        -c.hinge,
      );
    },
    SURFACE,
  );
  if (c.teeth) {
    add(
      jaw,
      `${kind}_lower_teeth`,
      () => dentition(kind, c, true).translate(0, -c.roof, -c.hinge),
      TEETH,
    );
    add(body, `${kind}_upper_teeth`, () => dentition(kind, c, false), TEETH);
  }
  // 旋齿鲨的螺旋齿列长在下颌中线内侧口腔中，上颌无齿；轮齿随下颌关节联动。
  if (kind === "helicoprion")
    add(jaw, `${kind}_tooth_whorl`, whorlGeometry, TEETH);
  motions.push((t, e) => {
    jaw.rotation.x =
      (c.jawBase ?? -0.012) -
      Math.sin(t * 0.43) * (0.012 + Math.min(e, 3) * 0.003);
  });
  add(body, `${kind}_head_details`, () => headDetails(kind, c), DARK);
  fins(kind, body, swimming, c, motions);
}

function dentition(kind, c, lower) {
  const parts = [],
    count = c.teeth.count;
  for (const side of [-1, 1])
    for (let i = 0; i < count; i++) {
      const t = (i + 0.5) / count,
        z = THREE.MathUtils.lerp(c.front + 0.02, c.hinge - 0.015, t),
        [rx] = sampleSection(c.profile, z),
        size = c.teeth.size * (0.75 + Math.sin(t * Math.PI) * 0.25),
        g = tooth(size, lower, false);
      // 鱼龙牙齿微向外撇，闭口时仍从唇缘露出。
      if (c.teeth.splay) g.rotateZ(side * c.teeth.splay);
      g.translate(
        side * rx * 0.82,
        c.roof -
          (lower
            ? c.gap * (1 - THREE.MathUtils.smoothstep(t, 0.55, 1)) + 0.001
            : 0),
        z,
      );
      parts.push(g);
    }
  return merge(parts);
}

/**
 * 旋齿鲨齿旋：约 2.4 圈对数螺旋的三角齿冠列，整体位于下颌联合处。
 * 复原依据 Tapanila 2013 的 CT 重建：齿旋完全包在口腔内，不外露于颌端。
 */
function whorlGeometry() {
  const parts = [],
    center = new THREE.Vector3(0, -0.024, -0.105),
    count = 22,
    spiral = [];
  for (let i = 0; i < count; i++) {
    const phi = THREE.MathUtils.degToRad(115 - 38 * i),
      r = 0.042 * 0.928 ** i,
      position = new THREE.Vector3(
        0,
        center.y + Math.sin(phi) * r,
        center.z + Math.cos(phi) * r,
      );
    spiral.push(position.clone());
    const size = 0.0195 * (r / 0.042) ** 0.7 + 0.0035,
      g = tooth(size, true, true);
    g.scale(0.55, 1, 1);
    g.applyQuaternion(
      new THREE.Quaternion().setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        new THREE.Vector3(0, Math.sin(phi), Math.cos(phi)).normalize(),
      ),
    );
    g.translate(position.x, position.y, position.z);
    parts.push(g);
  }
  // 齿冠共用的螺旋齿根带没入下颌软骨，外圈可见一截。
  const rootPoints = spiral
    .filter((_, i) => i % 2 === 0)
    .map((p, i) => p.clone().lerp(center, 0.18 + i * 0.01));
  const root = new THREE.TubeGeometry(
    new THREE.CatmullRomCurve3(rootPoints),
    40,
    0.0058,
    6,
    false,
  );
  parts.push(root);
  const g = merge(parts);
  // 几何缓存于下颌局部坐标，构建时平移到颌关节原点。
  return g;
}

/** 吻端鼻孔与鳃裂细节；旋齿鲨按全头类重建为单个鳃盖裂。 */
function headDetails(kind, c) {
  const parts = [];
  const nostril = {
    blue_shark: [0.026, -0.002, -0.44],
    swordfish: [0.03, 0.014, -0.288],
    ichthyosaur: [0.016, 0.026, -0.478],
    helicoprion: [0.026, -0.002, -0.44],
  }[kind];
  for (const side of [-1, 1])
    parts.push(
      blob(
        [side * nostril[0], nostril[1], nostril[2]],
        kind === "ichthyosaur"
          ? [0.003, 0.002, 0.004]
          : [0.007, 0.0022, 0.0035],
      ),
    );
  if (kind === "ichthyosaur") return merge(parts);
  if (kind === "helicoprion") {
    // 全头类鳃裂被皮褶鳃盖覆盖，只留一道弧形鳃盖缝。
    for (const side of [-1, 1])
      parts.push(
        tube(
          [
            [side * 0.088, 0.032, -0.248],
            [side * 0.097, 0.0, -0.238],
            [side * 0.091, -0.028, -0.228],
          ],
          0.0016,
        ),
      );
    return merge(parts);
  }
  if (kind === "swordfish") {
    // 硬骨鱼只有一道鳃盖后缘；曲线沿各高度的真实椭圆截面贴合。
    for (const side of [-1, 1]) {
      const points = [
        [0.68, -0.163],
        [0.4, -0.14],
        [0, -0.129],
        [-0.38, -0.141],
        [-0.65, -0.169],
      ].map(([f, z]) => {
        const [rx, ry, cy] = sampleSection(c.profile, z);
        return [side * (rx * Math.sqrt(1 - f * f) + 0.0008), cy + f * ry, z];
      });
      parts.push(tube(points, 0.0012, 24, 6));
    }
    return merge(parts);
  }
  // 蓝鲨的五道短鳃裂逐条贴合躯干表面。
  const slitZ = -0.212,
    slitCount = 5;
  for (const side of [-1, 1])
    for (let i = 0; i < slitCount; i++) {
      const z = slitZ + i * 0.013,
        [rx, ry, cy] = sampleSection(c.profile, z);
      const points = [0.3, 0.12, -0.08, -0.25].map((f) => {
        const y = cy + f * ry;
        return [
          side *
            (rx * Math.sqrt(Math.max(0.05, 1 - ((y - cy) / ry) ** 2)) + 0.001),
          y,
          z + (f < 0 ? 0.004 : 0),
        ];
      });
      parts.push(tube(points, kind === "blue_shark" ? 0.0011 : 0.0009));
    }
  return merge(parts);
}

/** 各物种差异化鳍式：胸鳍独立关节，正鳍与尾鳍按解剖轮廓成型。 */
function fins(kind, body, swimming, c, motions) {
  const pectoral = {
    blue_shark: {
      joint: [0.068, -0.05, -0.19],
      outline: [
        [-0.03, -0.01],
        [-0.02, 0.055],
        [0.05, 0.2],
        [0.13, 0.29],
        [0.185, 0.305],
        [0.175, 0.235],
        [0.105, 0.055],
        [0.04, -0.005],
      ],
      thickness: 0.014,
      flap: 0.035,
      base: -0.28,
    },
    swordfish: {
      joint: [0.06, -0.048, -0.13],
      outline: [
        [-0.037, -0.012],
        [-0.028, 0.04],
        [0.063, 0.172],
        [0.132, 0.207],
        [0.144, 0.155],
        [0.08, 0.029],
        [0.052, -0.01],
      ],
      thickness: 0.012,
      flap: 0.06,
      base: -0.16,
    },
    helicoprion: {
      joint: [0.1, -0.055, -0.15],
      outline: [
        [-0.04, -0.014],
        [-0.033, 0.045],
        [0.04, 0.17],
        [0.1, 0.2],
        [0.115, 0.15],
        [0.07, 0.03],
        [0.05, -0.012],
      ],
      thickness: 0.014,
      flap: 0.05,
      base: -0.2,
    },
  }[kind];
  if (pectoral) {
    for (const side of [-1, 1]) {
      const joint = new THREE.Group();
      joint.name = `${kind}_pectoral_${side}`;
      joint.position.set(
        side * pectoral.joint[0],
        pectoral.joint[1],
        pectoral.joint[2],
      );
      body.add(joint);
      add(
        joint,
        `${kind}_pectoral_mesh_${side}`,
        () => {
          const g = paint(
            sculptedFin(pectoral.outline, pectoral.thickness, "horizontal", {
              detail: 1,
              camber: 0.003,
            }),
            c.fin,
            c.side || c.belly,
          );
          return side < 0 ? mirror(g) : g;
        },
        SURFACE,
      );
      motions.push((t, e) => {
        joint.rotation.z =
          side *
          (pectoral.base +
            Math.sin(t * c.freq) *
              (pectoral.flap * 0.5 + Math.min(e, 3) * 0.012));
        joint.rotation.y = side * Math.cos(t * c.freq) * 0.025;
      });
    }
  }
  // 鱼龙四肢特化为两对鳍状肢，前肢明显大于后肢，仅作姿态微调。
  if (kind === "ichthyosaur") {
    const pairs = [
      { joint: [0.09, -0.075, -0.06], scale: 1.45, phase: 0, base: -0.3 },
      { joint: [0.076, -0.068, 0.2], scale: 0.82, phase: 1.4, base: -0.18 },
    ];
    for (const [index, limb] of pairs.entries())
      for (const side of [-1, 1]) {
        const joint = new THREE.Group();
        joint.name = `${kind}_${index === 0 ? "fore" : "hind"}_flipper_${side}`;
        joint.position.set(side * limb.joint[0], limb.joint[1], limb.joint[2]);
        body.add(joint);
        add(
          joint,
          `${kind}_flipper_mesh_${index}_${side}`,
          () => {
            const outline = [
              [-0.045, -0.016],
              [-0.04, 0.03],
              [0.0, 0.1],
              [0.05, 0.16],
              [0.09, 0.165],
              [0.1, 0.1],
              [0.06, 0.02],
              [0.02, -0.014],
            ].map(([z, y]) => [z * limb.scale, y * limb.scale]);
            const g = paint(
              sculptedFin(outline, 0.016 * limb.scale, "horizontal", {
                detail: 1,
                camber: 0.003,
              }),
              c.fin,
              c.side,
            );
            return side < 0 ? mirror(g) : g;
          },
          SURFACE,
        );
        motions.push((t, e) => {
          joint.rotation.x =
            Math.sin(t * c.freq * 0.5 + limb.phase) *
            (0.05 + Math.min(e, 3) * 0.01);
          joint.rotation.z =
            side *
            (limb.base + Math.sin(t * c.freq * 0.5 + limb.phase + 0.8) * 0.035);
        });
      }
  }
  add(
    body,
    `${kind}_median_fins`,
    () => {
      const parts = [];
      const fin = (outline, thickness = 0.011, options = { detail: 1 }) =>
        parts.push(
          paint(sculptedFin(outline, thickness, "vertical", options), c.fin),
        );
      if (kind === "blue_shark") {
        fin([
          [-0.01, 0.062],
          [0.035, 0.138],
          [0.075, 0.128],
          [0.09, 0.055],
          [0.11, 0.046],
        ]);
        fin([
          [0.28, 0.02],
          [0.305, 0.046],
          [0.325, 0.018],
        ]);
        fin([
          [0.17, -0.042],
          [0.2, -0.066],
          [0.23, -0.038],
        ]);
        fin([
          [0.28, -0.018],
          [0.31, -0.042],
          [0.33, -0.016],
        ]);
      } else if (kind === "swordfish") {
        // 成年剑鱼第一背鳍高而镰弯，无腹鳍，尾柄两侧各一枚大尾 keel。
        fin([
          [-0.145, 0.06],
          [-0.068, 0.213],
          [-0.03, 0.232],
          [-0.039, 0.167],
          [-0.003, 0.101],
          [0.07, 0.069],
        ]);
        fin([
          [0.33, 0.02],
          [0.355, 0.046],
          [0.375, 0.018],
        ]);
        fin([
          [0.01, -0.069],
          [0.085, -0.143],
          [0.102, -0.142],
          [0.105, -0.105],
          [0.18, -0.054],
        ]);
        fin([
          [0.34, -0.018],
          [0.36, -0.042],
          [0.375, -0.016],
        ]);
        for (const side of [-1, 1]) {
          const keel = paint(
            sculptedFin(
              [
                [0.345, 0.008],
                [0.365, 0.034],
                [0.41, 0.028],
                [0.42, 0.008],
              ],
              0.006,
              "horizontal",
              { detail: 0 },
            ),
            c.fin,
          );
          if (side < 0) mirror(keel);
          keel.translate(side * 0.008, 0, 0);
          parts.push(keel);
        }
      } else if (kind === "ichthyosaur") {
        fin([
          [0.02, 0.1],
          [0.08, 0.158],
          [0.16, 0.096],
        ]);
      } else if (kind === "helicoprion") {
        fin([
          [-0.06, 0.098],
          [0.0, 0.178],
          [0.05, 0.162],
          [0.07, 0.092],
        ]);
        fin([
          [0.16, 0.056],
          [0.21, 0.102],
          [0.25, 0.05],
        ]);
        fin([
          [0.15, -0.046],
          [0.19, -0.076],
          [0.23, -0.042],
        ]);
        fin([
          [0.27, -0.02],
          [0.3, -0.046],
          [0.33, -0.018],
        ]);
      }
      return merge(parts);
    },
    SURFACE,
  );
  const tail = new THREE.Group();
  tail.name = `${kind}_tail`;
  swimming.skeleton.bones[2].add(tail);
  tail.position.set(
    0,
    kind === "ichthyosaur" ? -0.058 : 0,
    c.profile.at(-1)[0] - 0.265,
  );
  add(
    tail,
    `${kind}_caudal`,
    () => {
      const outline =
        kind === "swordfish"
          ? [
              [-0.015, -0.02],
              [0.06, -0.1],
              [0.1, -0.155],
              [0.115, -0.14],
              [0.085, -0.06],
              [0.065, -0.01],
              [0.085, 0.05],
              [0.115, 0.14],
              [0.1, 0.155],
              [0.06, 0.1],
              [-0.015, 0.025],
            ]
          : kind === "ichthyosaur"
            ? [
                [-0.023, -0.023],
                [0.052, -0.086],
                [0.098, -0.121],
                [0.115, -0.109],
                [0.08, -0.046],
                [0.058, -0.006],
                [0.08, 0.052],
                [0.115, 0.115],
                [0.132, 0.132],
                [0.104, 0.069],
                [0.058, 0.023],
                [-0.023, 0.012],
              ]
            : [
                [-0.02, -0.008],
                [0.075, -0.115],
                [0.105, -0.135],
                [0.1, -0.085],
                [0.055, -0.012],
                [0.06, 0.02],
                [0.16, 0.19],
                [0.2, 0.225],
                [0.185, 0.16],
                [0.1, 0.075],
                [0.045, 0.05],
                [-0.02, 0.015],
              ];
      return paint(
        sculptedFin(outline, kind === "swordfish" ? 0.013 : 0.015, "vertical", {
          detail: 1,
          camber: 0.001,
        }),
        c.fin,
        c.side,
      );
    },
    SURFACE,
  );
  motions.push((t, e) => {
    tail.rotation.y =
      Math.sin(t * c.freq - 1.5) *
      (0.085 + Math.min(e, 3) * 0.014) *
      (kind === "swordfish" ? 1.15 : 1);
  });
}

creature_ecosystem.js.source:
import * as THREE from "three";
import {
  bindAxialMotion,
  skinMaterial,
  sampleSection,
  sculptedFin,
} from "./creature_surface.js";
import { buildOctopus } from "./creature_octopus.js";
import { buildReefCreature } from "./creature_reef.js";

/** 新生态模型拥有独立剪影；几何与材质按物种缓存，群游实例不重复创建资产。 */
export const ECOSYSTEM_CREATURE_KINDS = new Set([
  "boxfish",
  "parrotfish",
  "wrasse",
  "sardine",
  "anchovy",
  "herring",
  "mackerel",
  "flying_fish",
  "turtle",
  "sunfish",
  "hammerhead",
  "sperm_whale",
  "octopus",
  "mosasaur",
  "plesiosaur",
  "megalodon",
  "pliosaur",
  "basilosaurus",
]);

/**
 * 向根节点填充新生物模型，头朝 -Z；归一化后的纵向全长为 1。
 * @param {string} kind 物种标识。
 * @param {THREE.Group} root 创建入口的根节点。
 * @param {Function[]} motions 由统一游泳时钟更新的动作函数。
 * @returns {void} 模型与动作写入参数；飞鱼读取 root.userData.airborne 展翼。
 */
export function buildEcosystemCreature(kind, root, motions) {
  if (kind === "flying_fish") {
    root.userData.setGliding = (active) => {
      root.userData.airborne = Boolean(active);
    };
  }
  const body = new THREE.Group();
  body.name = `${kind}_anatomy`;
  root.add(body);
  if (["boxfish", "parrotfish", "wrasse"].includes(kind))
    buildReefCreature(kind, body, motions);
  else if (SMALL_FISH[kind]) buildSchoolFish(kind, body, motions, root);
  else if (kind === "turtle") buildTurtle(body, motions);
  else if (kind === "sunfish") buildSunfish(body, motions);
  else if (kind === "hammerhead" || kind === "megalodon")
    buildPredatoryShark(kind, body, motions);
  else if (kind === "sperm_whale") buildSpermWhale(body, motions);
  else if (kind === "octopus") buildOctopus(body, motions);
  else if (kind === "basilosaurus") buildBasilosaurus(body, motions);
  else buildReptile(kind, body, motions);
  body.updateMatrixWorld(true);
  const bounds = new THREE.Box3().setFromObject(body);
  const size = bounds.getSize(new THREE.Vector3());
  const center = bounds.getCenter(new THREE.Vector3());
  const scale = 1 / size.z;
  body.scale.setScalar(scale);
  body.position.copy(center).multiplyScalar(-scale);
  root.userData.normalizedLength = 1;
}

const GEOMETRIES = new Map();
const MATERIALS = new Map();
const SPHERE = new THREE.SphereGeometry(1, 12, 8);
const EYE = material("#091821", 0.12);
const PALE = material("#e2e8cf", 0.46);
const DARK = material("#17313d", 0.64);
const SILVER = material("#d7e6e5", 0.24);
const SMALL_FISH = {
  sardine: {
    width: 0.085,
    height: 0.115,
    back: "#286c78",
    belly: "#d9e6de",
    tail: 0.15,
  },
  anchovy: {
    width: 0.052,
    height: 0.064,
    back: "#406c73",
    belly: "#e8e4c8",
    tail: 0.105,
  },
  herring: {
    width: 0.077,
    height: 0.16,
    back: "#485d87",
    belly: "#e3e7ea",
    tail: 0.18,
  },
  mackerel: {
    width: 0.103,
    height: 0.13,
    back: "#2a737c",
    belly: "#dae4cb",
    tail: 0.19,
  },
  flying_fish: {
    width: 0.068,
    height: 0.079,
    back: "#347da7",
    belly: "#d6e9df",
    tail: 0.18,
  },
};

function buildSchoolFish(kind, body, motions, root) {
  const config = SMALL_FISH[kind];
  const torso = add(
    body,
    cached(`${kind}_body`, () =>
      loft(
        [
          [-0.49, 0.008, 0.012],
          [-0.4, config.width * 0.54, config.height * 0.5],
          [-0.24, config.width, config.height],
          [0.01, config.width, config.height],
          [0.25, config.width * 0.52, config.height * 0.57],
          [0.38, 0.013, 0.023],
        ],
        config.back,
        config.belly,
        { school: true },
      ),
    ),
    schoolMaterial(kind),
  );
  bindAxialMotion(torso, motions, {
    axis: "y",
    frequency: 2.2,
    amplitude: 0.065,
  });
  eyes(
    body,
    config.width * 0.78,
    0.018,
    -0.36,
    kind === "anchovy" ? 0.011 : 0.014,
  );
  for (const side of [-1, 1]) {
    tube(
      body,
      `${kind}_operculum_${side}`,
      [
        [side * config.width * 0.87, config.height * 0.42, -0.275],
        [side * config.width * 0.985, 0, -0.252],
        [side * config.width * 0.82, -config.height * 0.5, -0.269],
      ],
      0.0013,
      EYE,
    );
    tube(
      body,
      `${kind}_lip_${side}`,
      [
        [0, -0.008, -0.49],
        [side * config.width * 0.24, -0.016, -0.458],
        [side * config.width * 0.42, -0.019, -0.424],
      ],
      0.0013,
      EYE,
    );
  }
  const tail = pivot(body, [0, 0, 0.34]);
  fin(
    tail,
    `${kind}_tail`,
    [
      [0, 0, 0],
      [0, config.tail, 0.19],
      [0, 0, 0.13],
      [0, -config.tail, 0.19],
    ],
    material(config.back),
  );
  motions.push((t, e) => {
    tail.rotation.y = Math.sin(t * 2.2) * (0.22 + e * 0.035);
  });
  fin(
    body,
    `${kind}_dorsal`,
    [
      [0, config.height * 0.8, -0.1],
      [0, config.height + 0.095, -0.04],
      [0, config.height * 0.65, 0.12],
    ],
    material(config.back),
  );
  for (const side of [-1, 1]) {
    if (kind === "flying_fish") {
      const pectoral = pivot(body, [side * config.width * 0.65, -0.025, -0.22]);
      fin(
        pectoral,
        `fly_wing_${side}`,
        [
          [0, 0, 0],
          [side * 0.49, -0.014, 0.1],
          [side * 0.46, -0.024, 0.29],
          [side * 0.07, -0.02, 0.36],
        ],
        material("#85b9d8", 0.3),
      );
      for (let i = 1; i <= 4; i++)
        tube(
          pectoral,
          `fly_ray_${side}_${i}`,
          [
            [0, 0, 0],
            [side * (0.17 + i * 0.065), -0.006, 0.1 + i * 0.043],
          ],
          0.0025,
          SILVER,
        );
      motions.push((t) => {
        pectoral.rotation.z =
          side * (root.userData.airborne ? 0.04 : 0.5 + Math.sin(t) * 0.06);
      });
    } else {
      fin(
        body,
        `${kind}_pectoral_${side}`,
        [
          [side * config.width * 0.65, -0.025, -0.22],
          [side * (config.width * 0.65 + 0.08), -0.1, -0.12],
          [side * config.width * 0.65, -0.025, -0.14],
        ],
        material(config.back),
      );
    }
  }
  if (kind === "anchovy") {
    for (const side of [-1, 1])
      tube(
        body,
        `anchovy_band_${side}`,
        [
          [side * 0.035, 0, -0.38],
          [side * 0.054, 0, -0.16],
          [side * 0.046, 0, 0.16],
          [side * 0.017, 0, 0.33],
        ],
        0.006,
        material("#f1dea1"),
      );
    ellipsoid(body, SILVER, [0, -0.028, -0.39], [0.029, 0.017, 0.1]);
  }
  if (kind === "herring") {
    for (let i = 0; i < 9; i++)
      fin(
        body,
        `herring_keel_${i}`,
        [
          [0, -0.14 + i * 0.006, -0.2 + i * 0.045],
          [0, -0.167 + i * 0.006, -0.18 + i * 0.045],
          [0, -0.13 + i * 0.006, -0.15 + i * 0.045],
        ],
        PALE,
      );
  }
  if (kind === "mackerel") {
    for (let i = 0; i < 4; i++)
      fin(
        body,
        `mackerel_finlet_${i}`,
        [
          [0, 0.055, 0.2 + i * 0.04],
          [0, 0.09, 0.21 + i * 0.04],
          [0, 0.035, 0.245 + i * 0.04],
        ],
        material("#abca84"),
      );
  }
}

function buildTurtle(body, motions) {
  const shell = material("#505c37", 0.57),
    skin = material("#7f8860", 0.6);
  const carapace = add(
    body,
    cached("turtle_carapace", () => {
      const g = new THREE.SphereGeometry(1, 40, 24),
        p = g.attributes.position;
      for (let i = 0; i < p.count; i++)
        if (p.getY(i) < 0) p.setY(i, p.getY(i) * 0.25);
      g.computeVertexNormals();
      return g;
    }),
    shell,
  );
  carapace.position.set(0, 0.025, 0);
  carapace.scale.set(0.32, 0.16, 0.37);
  ellipsoid(
    body,
    material("#c0b887", 0.65),
    [0, -0.025, 0],
    [0.29, 0.037, 0.34],
  );
  // 盾片边界沿同一连续背甲投影，避免把龟甲拼成一排悬浮椭球。
  const seam = material("#3b4329", 0.62);
  const shellY = (x, z) =>
    0.026 +
    0.162 * Math.sqrt(Math.max(0.02, 1 - (x / 0.32) ** 2 - (z / 0.37) ** 2));
  for (let i = 0; i < 5; i++) {
    const z = -0.255 + i * 0.126;
    const width = 0.083 * Math.sqrt(Math.max(0.3, 1 - (z / 0.38) ** 2));
    const shield = [
      [0, z - 0.073],
      [-width, z - 0.031],
      [-width, z + 0.036],
      [0, z + 0.071],
      [width, z + 0.036],
      [width, z - 0.031],
      [0, z - 0.073],
    ];
    tube(
      body,
      `turtle_shield_${i}`,
      shield.map(([x, pz]) => [x, shellY(x, pz), pz]),
      0.0022,
      seam,
    );
    for (const side of [-1, 1]) {
      const x = side * width,
        outerX = side * 0.27 * Math.sqrt(Math.max(0.1, 1 - (z / 0.37) ** 2));
      tube(
        body,
        `turtle_lateral_${side}_${i}`,
        [
          [x, shellY(x, z), z],
          [outerX * 0.85, shellY(outerX * 0.85, z + 0.025), z + 0.025],
          [outerX, shellY(outerX, z + 0.06), z + 0.06],
        ],
        0.002,
        seam,
      );
    }
  }
  ellipsoid(body, skin, [0, 0, -0.395], [0.088, 0.075, 0.13]);
  eyes(body, 0.075, 0.023, -0.44, 0.011);
  for (const side of [-1, 1]) {
    tube(
      body,
      `turtle_beak_${side}`,
      [
        [0, -0.022, -0.519],
        [side * 0.06, -0.028, -0.484],
        [side * 0.078, -0.014, -0.43],
      ],
      0.0025,
      DARK,
    );
    ellipsoid(body, DARK, [side * 0.026, 0.028, -0.503], [0.007, 0.005, 0.004]);
  }
  for (const side of [-1, 1]) {
    const front = pivot(body, [side * 0.21, -0.02, -0.21]);
    fin(
      front,
      `turtle_front_${side}`,
      [
        [0, 0, 0],
        [side * 0.22, -0.03, -0.01],
        [side * 0.38, -0.025, 0.18],
        [side * 0.21, 0.0, 0.15],
        [side * 0.04, 0, 0.1],
      ],
      skin,
    );
    const rear = pivot(body, [side * 0.19, -0.03, 0.24]);
    fin(
      rear,
      `turtle_rear_${side}`,
      [
        [0, 0, 0],
        [side * 0.22, -0.025, 0.04],
        [side * 0.2, 0, 0.18],
        [side * 0.06, 0, 0.12],
      ],
      skin,
    );
    motions.push((t, e) => {
      front.rotation.z = side * Math.sin(t * 0.8) * 0.38;
      rear.rotation.z = side * Math.sin(t * 0.8 + 1) * 0.14;
      front.rotation.y = side * Math.sin(t * 0.8) * 0.08 * e;
    });
  }
  ellipsoid(body, skin, [0, -0.02, 0.38], [0.035, 0.03, 0.08]);
}

