function material(color, roughness = 0.46) {
  const key = `${color}_${roughness}`;
  if (!MATERIALS.has(key))
    MATERIALS.set(
      key,
      skinMaterial({
        color,
        roughness,
        metalness: 0.015,
        side: THREE.DoubleSide,
      }),
    );
  return MATERIALS.get(key);
}
function schoolMaterial(kind) {
  const key = `school_skin_${kind}`;
  if (!MATERIALS.has(key)) {
    const mat = skinMaterial({
      vertexColors: true,
      roughness: 0.31,
      metalness: 0.1,
      clearcoat: 0.25,
      pattern: 0.005,
    });
    const compile = mat.onBeforeCompile;
    mat.onBeforeCompile = (shader) => {
      compile(shader);
      const pattern =
        kind === "mackerel"
          ? `
        float stripe = 1.0 - smoothstep(0.38,0.68,abs(sin(vSkinPosition.z*142.0+sin(vSkinPosition.x*72.0)*1.9)));
        stripe *= smoothstep(0.025,0.078,vSkinPosition.y)*smoothstep(-0.3,-0.2,vSkinPosition.z)*(1.0-smoothstep(0.2,0.3,vSkinPosition.z));
        diffuseColor.rgb *= 1.0 - stripe*0.56;
      `
          : kind === "sardine"
            ? `
        float spotZ=mod(vSkinPosition.z+0.17,0.065)-0.0325;
        float spot=1.0-smoothstep(0.006,0.011,length(vec2(spotZ,vSkinPosition.y-0.026)));
        spot*=smoothstep(-0.22,-0.16,vSkinPosition.z)*(1.0-smoothstep(0.17,0.22,vSkinPosition.z));
        diffuseColor.rgb*=1.0-spot*0.65;
      `
            : "";
      shader.fragmentShader = shader.fragmentShader.replace(
        "#include <roughnessmap_fragment>",
        pattern + "\n#include <roughnessmap_fragment>",
      );
    };
    mat.customProgramCacheKey = () => key;
    MATERIALS.set(key, mat);
  }
  return MATERIALS.get(key);
}

function vertexMaterial() {
  if (!MATERIALS.has("vertex"))
    MATERIALS.set(
      "vertex",
      skinMaterial({
        vertexColors: true,
        roughness: 0.43,
        metalness: 0.015,
      }),
    );
  return MATERIALS.get("vertex");
}
function cached(key, make) {
  if (!GEOMETRIES.has(key)) GEOMETRIES.set(key, make());
  return GEOMETRIES.get(key);
}
function add(parent, geometry, mat) {
  const mesh = new THREE.Mesh(geometry, mat);
  parent.add(mesh);
  return mesh;
}
function pivot(parent, position) {
  const group = new THREE.Group();
  group.position.set(...position);
  parent.add(group);
  return group;
}
function ellipsoid(parent, mat, position, scale) {
  const mesh = add(parent, SPHERE, mat);
  mesh.position.set(...position);
  mesh.scale.set(...scale);
  return mesh;
}
function eyes(parent, x, y, z, radius) {
  for (const side of [-1, 1]) {
    ellipsoid(
      parent,
      PALE,
      [side * x, y, z],
      [radius * 1.2, radius * 1.2, radius * 1.2],
    );
    ellipsoid(
      parent,
      EYE,
      [side * (x + radius * 0.6), y, z - radius * 0.1],
      [radius * 0.7, radius * 0.8, radius * 0.9],
    );
  }
}
function fin(parent, key, points, mat) {
  const geometry = cached(key, () => {
    const horizontal = Math.max(...points.map((p) => Math.abs(p[0]))) > 0.001;
    const outline = points.map((p) => [p[2], horizontal ? p[0] : p[1]]);
    const g = sculptedFin(
      outline,
      0.009,
      horizontal ? "horizontal" : "vertical",
      {
        camber: 0.006,
        detail: /^(sardine|anchovy|herring|mackerel|flying_fish|fly_)/.test(key)
          ? 1
          : 2,
      },
    );
    if (horizontal)
      g.translate(
        0,
        points.reduce((sum, p) => sum + p[1], 0) / points.length,
        0,
      );
    return g;
  });
  return add(parent, geometry, mat);
}

function tube(parent, key, points, radius, mat) {
  return add(
    parent,
    cached(
      key,
      () =>
        new THREE.TubeGeometry(
          new THREE.CatmullRomCurve3(
            points.map((p) => new THREE.Vector3(...p)),
          ),
          /operculum|_lip_/.test(key) ? 4 : Math.max(4, points.length * 3),
          radius,
          /operculum|_lip_/.test(key) ? 3 : 4,
          false,
        ),
    ),
    mat,
  );
}
function jaw(parent, key, width, y, z, halfLength, teeth) {
  ellipsoid(parent, material("#26333b"), [0, y, z], [width, 0.023, halfLength]);
  for (const side of [-1, 1])
    for (let i = 0; i < teeth; i++) {
      const position = [
        side * width * (0.45 + Math.sin((i / (teeth - 1)) * Math.PI) * 0.42),
        y - 0.004,
        z - halfLength * 0.8 + (i / (teeth - 1)) * halfLength * 1.6,
      ];
      const tooth = add(
        parent,
        cached(`${key}_tooth`, () => new THREE.ConeGeometry(0.0045, 0.015, 5)),
        PALE,
      );
      tooth.position.set(...position);
      tooth.rotation.z = Math.PI;
    }
}
function loft(profile, upper, lower, options = {}) {
  const positions = [],
    colors = [],
    indices = [],
    sides = options.school ? 18 : 24,
    rings = (profile.length - 1) * (options.school ? 5 : 6);
  const top = new THREE.Color(upper),
    bottom = new THREE.Color(lower),
    color = new THREE.Color();
  for (let ring = 0; ring <= rings; ring++) {
    const z = THREE.MathUtils.lerp(
      profile[0][0],
      profile.at(-1)[0],
      ring / rings,
    );
    const [rx, ry, offset] = sampleSection(profile, z);
    for (let side = 0; side <= sides; side++) {
      const angle = (side / sides) * Math.PI * 2,
        y = Math.sin(angle);
      const exponent = options.squareFront
        ? THREE.MathUtils.lerp(
            0.66,
            1,
            THREE.MathUtils.smoothstep(z, -0.25, -0.08),
          )
        : 1;
      const xSection =
        Math.sign(Math.cos(angle)) * Math.abs(Math.cos(angle)) ** exponent;
      const ySection = Math.sign(y) * Math.abs(y) ** exponent;
      positions.push(xSection * rx, ySection * ry + offset, z);
      color
        .copy(top)
        .lerp(bottom, 1 - THREE.MathUtils.smoothstep(y, -0.48, 0.18));
      colors.push(color.r, color.g, color.b);
      if (ring < rings && side < sides) {
        const p = ring * (sides + 1) + side,
          q = p + sides + 1;
        indices.push(p, p + 1, q, p + 1, q + 1, q);
      }
    }
  }
  // 封闭首尾截面，近距离与碰撞射线不穿过模型端部。
  for (const end of [0, 1]) {
    const center = positions.length / 3;
    positions.push(0, 0, profile[end ? profile.length - 1 : 0][0]);
    colors.push(top.r, top.g, top.b);
    const base = end ? rings * (sides + 1) : 0;
    for (let side = 0; side < sides; side++) {
      if (end) indices.push(center, base + side, base + side + 1);
      else indices.push(center, base + side + 1, base + side);
    }
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute(
    "position",
    new THREE.Float32BufferAttribute(positions, 3),
  );
  geometry.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

creature_extra.js.source:
import * as THREE from "three";
import { bindPlayerAppendage, addFeedingMouth } from "./player_motion.js";
import {
  skinMaterial,
  sampleSection,
  sculptedFin,
} from "./creature_surface.js";

export const EXTRA_CREATURE_KINDS = new Set([
  "squid",
  "dunkleosteus",
  "mayan",
  "hydra",
  "kraken",
  "seagull",
]);

/**
 * 构建扩展生物的归一化模型，供 createCreature 统一缩放及更新动画。
 * @param {string} kind 扩展生物名称。
 * @param {THREE.Group} root 模型根节点，前进方向为 -Z。
 * @param {Function[]} motions 动作回调列表，参数为累计游泳相位和速度强度。
 * @returns {void} 模型直接添加到 root。
 */
export function buildExtraCreature(kind, root, motions) {
  if (kind === "squid") buildSquid(root, motions);
  else if (kind === "kraken") buildKraken(root, motions);
  else if (kind === "dunkleosteus") buildDunkleosteus(root, motions);
  else if (kind === "mayan") buildMayan(root, motions);
  else if (kind === "hydra") buildHydra(root, motions);
  else if (kind === "seagull") buildSeagull(root, motions);
}

const CACHE = new Map();
const SPHERE = new THREE.SphereGeometry(1, 20, 14);
const SUCKER = new THREE.TorusGeometry(0.72, 0.28, 4, 8);
const FACET = new THREE.IcosahedronGeometry(1, 1);
const BOX = new THREE.BoxGeometry(1, 1, 1);
const M = {
  body: material("#ffffff", 0.45, "#000000", 0, { vertexColors: true }),
  squid: material("#a5634b", 0.43),
  squidFin: material("#bb8065", 0.48),
  sucker: material("#d9b89a", 0.52),
  kraken: material("#2a2340", 0.46),
  krakenRidge: material("#4a3f66", 0.55),
  krakenSucker: material("#c49bc4", 0.6),
  armor: material("#5a6963", 0.6),
  armorDark: material("#2c383f", 0.55),
  bone: material("#cfc9a8", 0.48),
  jade: material("#237c74", 0.46),
  jadeDark: material("#143a3e", 0.56),
  gold: material("#c8a24c", 0.36, "#554016", 0.22),
  hydra: material("#1e474b", 0.45),
  hydraFin: material("#2f6560", 0.58),
  white: material("#e9eee8", 0.62),
  gray: material("#9aa8ab", 0.68),
  wingtip: material("#2b3a42", 0.65),
  yellow: material("#deab49", 0.5),
  black: material("#040a11", 0.18),
  glow: material("#7ee6cf", 0.32, "#25cdbb", 1.7),
  amber: material("#ffcb77", 0.3, "#ff8d24", 1.8),
  violet: material("#a886e2", 0.4, "#7947d7", 1.3),
};

function buildSquid(root, motions) {
  const inner = new THREE.Group();
  inner.name = "squid_swimming_frame";
  // 默认采用外套膜尾端领先、腕足拖后的 tail-first 游姿；大王乌贼也能腕端领先游动。
  inner.rotation.y = 0;
  root.add(inner);
  addFeedingMouth(root, inner, [0, -0.004, 0.09]);
  // 巡游、冲刺和喷射保持相同朝向，依靠鳍与外套膜表达推进。
  const mantle = add(
    inner,
    cached("squid_mantle", () =>
      formColored(
        [
          [-0.5, 0.002, 0.004],
          [-0.44, 0.03, 0.04],
          [-0.3, 0.058, 0.071],
          [-0.14, 0.052, 0.063],
          [0.0, 0.036, 0.043],
          [0.08, 0.026, 0.03],
        ],
        "#985039",
        "#cfaa88",
      ),
    ),
    M.body,
  );
  mantle.name = "squid_mantle";
  mantle.userData.keepSeparate = true;
  for (const side of [-1, 1]) {
    // 独立鳍骨骼让波沿鳍缘传播，冲刺时逐渐收拢。
    const fin = new THREE.Group();
    fin.name = `squid_fin_${side}`;
    inner.add(fin);
    add(
      fin,
      cached(`squid_fin_${side}`, () =>
        finSolid(
          mirrorOutline(
            [
              [-0.5, 0.02],
              [-0.44, 0.1],
              [-0.3, 0.118],
              [-0.21, 0.05],
            ],
            side,
          ),
          0.006,
          "horizontal",
          { bevel: 0.003 },
        ),
      ),
      M.squidFin,
    );
    const finBones = bindPlayerAppendage(
      fin,
      `squid_fin_${side}`,
      [-0.5, -0.4, -0.3, -0.2],
    );
    motions.push((t, effort, state) => {
      const folded = Math.max(state.boost, state.jet);
      fin.rotation.z = -side * (0.22 + folded * 0.64);
      finBones.forEach((bone, index) => {
        bone.rotation.x =
          Math.sin(t * 1.35 - index * 0.95) *
          (0.16 - folded * 0.1) *
          (index ? 1 : 0.35);
        bone.rotation.z =
          side * Math.sin(t * 1.35 - index * 0.85) * (0.15 - folded * 0.09);
      });
    });
    // 虹膜嵌入连续头部，眼球仅略高于皮肤，避免球形眼柄。
    blob(inner, M.squidFin, [side * 0.041, 0, 0.047], [0.008, 0.025, 0.027]);
    blob(inner, M.black, [side * 0.047, 0, 0.047], [0.004, 0.02, 0.023]);
  }
  // 头领从外套膜平滑过渡到腕冠，腹面的漏斗用于喷流。
  add(
    inner,
    cached("squid_head", () =>
      formColored(
        [
          [-0.015, 0.027, 0.03],
          [0.023, 0.042, 0.037],
          [0.067, 0.037, 0.03],
          [0.105, 0.026, 0.025],
        ],
        "#a5634b",
        "#cfaa88",
      ),
    ),
    M.body,
  );
  blob(inner, M.squidFin, [0, -0.029, 0.034], [0.013, 0.012, 0.036]);
  blob(inner, M.black, [0, -0.032, 0.067], [0.008, 0.006, 0.003]);
  add(
    inner,
    cached("squid_arm_web", () => {
      const positions = [],
        indices = [];
      for (let segment = 0; segment <= 64; segment++) {
        const angle = (segment / 64) * Math.PI * 2;
        const reach = 0.057 + 0.017 * Math.cos((segment / 8) * Math.PI * 2);
        for (let ring = 0; ring <= 4; ring++) {
          const t = ring / 4,
            r = 0.021 + t * reach;
          positions.push(
            Math.cos(angle) * r,
            Math.sin(angle) * r * 0.9 - 0.004,
            0.081 + t * (0.075 + reach * 0.2),
          );
          if (segment < 64 && ring < 4) {
            const a = segment * 5 + ring;
            indices.push(a, a + 1, a + 5, a + 1, a + 6, a + 5);
          }
        }
      }
      const g = new THREE.BufferGeometry();
      g.setAttribute(
        "position",
        new THREE.Float32BufferAttribute(positions, 3),
      );
      g.setIndex(indices);
      g.computeVertexNormals();
      return g;
    }),
    M.squid,
  );
  blob(inner, M.black, [0, -0.004, 0.099], [0.013, 0.012, 0.015]);
  // 八条腕足以连续蒙皮变形，吸盘与腕部共享权重，根部保持稳定。
  for (let index = 0; index < 8; index++) {
    const angle = (index / 8) * Math.PI * 2;
    const c = Math.cos(angle),
      s = Math.sin(angle);
    const curl = Math.sin(index * 2.4) * 0.05;
    const arm = new THREE.Group();
    arm.position.set(c * 0.024, s * 0.022 - 0.004, 0.075);
    inner.add(arm);
    add(
      arm,
      cached(`squid_arm_${index}`, () =>
        tendril(
          [
            [0, 0, 0],
            [c * 0.07, s * 0.065, 0.13],
            [c * 0.1 + curl, s * 0.09, 0.28],
            [c * 0.085 + curl * 1.6, s * 0.08 + curl * 0.5, 0.38],
          ],
          0.013,
          0.0018,
        ),
      ),
      M.squid,
    );
    const cupCurve = curveFrom([
      [0, 0, 0],
      [c * 0.07, s * 0.065, 0.13],
      [c * 0.1 + curl, s * 0.09, 0.28],
      [c * 0.085 + curl * 1.6, s * 0.08 + curl * 0.5, 0.38],
    ]);
    for (let cup = 0; cup < 7; cup++) {
      const progress = 0.12 + cup * 0.105,
        center = cupCurve.getPointAt(progress);
      const radius = THREE.MathUtils.lerp(0.013, 0.0018, progress);
      for (const row of [-1, 1]) {
        const sucker = add(arm, SUCKER, M.sucker);
        sucker.position
          .copy(center)
          .add(
            new THREE.Vector3(
              -c * radius + s * radius * row * 0.33,
              -s * radius - c * radius * row * 0.33,
              0,
            ),
          );
        sucker.quaternion.setFromUnitVectors(
          new THREE.Vector3(0, 0, 1),
          new THREE.Vector3(-c, -s, 0),
        );
        sucker.scale.setScalar(radius * 0.47);
      }
    }
    const bones = bindPlayerAppendage(
      arm,
      `squid_arm_${index}`,
      [0, 0.08, 0.17, 0.27, 0.38],
    );
    motions.push((t, effort, state) => {
      const folded = Math.max(state.boost, state.jet);
      bones.forEach((bone, joint) => {
        const distal = joint / (bones.length - 1);
        const wave =
          Math.sin(t - joint * 0.8 + angle) *
          (0.04 + distal * 0.15) *
          (1 - folded * 0.48);
        const curl = state.feed * distal * 0.52;
        const narrow = folded * 0.055;
        bone.rotation.x =
          -s * wave +
          c * Math.sin(t - joint * 0.9 + angle) * distal * 0.035 +
          s * (narrow + curl) -
          state.pitchInput * distal * 0.035;
        bone.rotation.y =
          c * wave - c * (narrow + curl) + state.turn * distal * 0.075;
      });
    });
  }
  // 两条捕食触腕显著更长，末端带穗状吸盘球。
  for (const side of [-1, 1]) {
    const tentacle = new THREE.Group();
    tentacle.position.set(side * 0.018, -0.02, 0.08);
    inner.add(tentacle);
    add(
      tentacle,
      cached(`squid_tentacle_${side}`, () =>
        tendril(
          [
            [0, 0, 0],
            [side * 0.05, -0.03, 0.18],
            [side * 0.09, -0.04, 0.36],
            [side * 0.1, -0.03, 0.46],
          ],
          0.008,
          0.0032,
        ),
      ),
      M.squid,
    );
    blob(
      tentacle,
      M.squidFin,
      [side * 0.1, -0.028, 0.49],
      [0.017, 0.009, 0.05],
    );
    for (let index = 0; index < 6; index++) {
      blob(
        tentacle,
        M.sucker,
        [side * (0.1 - 0.004), -0.036, 0.468 + index * 0.012],
        [0.005, 0.003, 0.005],
      );
    }
    const bones = bindPlayerAppendage(
      tentacle,
      `squid_tentacle_${side}`,
      [0, 0.1, 0.21, 0.33, 0.44, 0.54],
    );
    motions.push((t, effort, state) => {
      const folded = Math.max(state.boost, state.jet);
      bones.forEach((bone, joint) => {
        const distal = joint / (bones.length - 1);
        bone.rotation.x =
          Math.sin(t * 0.9 - joint * 0.82 + side * 0.4) *
            (0.025 + distal * 0.17) *
            (1 - folded * 0.48) +
          state.feed * distal * 0.62;
        bone.rotation.y =
          side * Math.sin(t * 0.9 - joint * 0.85) * distal * 0.095 -
          side * (folded * 0.025 + state.feed * distal * 0.3) +
          state.turn * distal * 0.075;
      });
    });
  }
  motions.push((t, effort, state) => {
    const pulse = Math.sin(t * 1.4);
    const contraction =
      (0.025 + state.power * 0.025 + state.jet * 0.065) * (0.5 + pulse * 0.5);
    mantle.scale.set(1 - contraction, 1 - contraction, 1 + contraction * 0.24);
    mantle.position.z = -0.08 * contraction * 0.24;
    inner.rotation.z = state.turn * 0.12;
    Object.assign(root.userData.pose, {
      mantleContraction: contraction,
      finFold: Math.max(state.boost, state.jet),
      bank: inner.rotation.z,
      armPhase: t,
      feed: state.feed,
    });
  });
}

function buildKraken(root, motions) {
  const inner = new THREE.Group();
  root.add(inner);
  // 巨大球状头胸低坐在后，八条粗腕向前张开，与火箭形乌贼严格区分。
  const head = new THREE.Group();
  inner.add(head);
  add(
    head,
    cached("kraken_mantle", () =>
      formColored(
        [
          [-0.08, 0.17, 0.16],
          [0.06, 0.225, 0.22],
          [0.24, 0.2, 0.205],
          [0.38, 0.125, 0.135],
          [0.48, 0.028, 0.04],
        ],
        "#241f3d",
        "#453a63",
      ),
    ),
    M.body,
  );
  for (const side of [-1, 1]) {
    // 琥珀色横瞳巨眼与压顶的眉脊，构成正面威慑。
    blob(head, M.black, [side * 0.118, 0.005, -0.07], [0.036, 0.042, 0.022]);
    blob(head, M.amber, [side * 0.123, 0.006, -0.08], [0.025, 0.031, 0.015]);
    const pupil = blob(
      head,
      M.black,
      [side * 0.125, 0.007, -0.09],
      [0.006, 0.021, 0.006],
    );
    pupil.rotation.x = 0.2;
    const brow = blob(
      head,
      M.krakenRidge,
      [side * 0.11, 0.068, -0.055],
      [0.09, 0.032, 0.055],
      true,
    );
    brow.rotation.z = -side * 0.34;
    // 头顶四根后弯犄角。
    add(
      head,
      cached(`kraken_horn_${side}`, () =>
        tendril(
          [
            [side * 0.07, 0.14, 0.08],
            [side * 0.1, 0.22, 0.16],
            [side * 0.11, 0.26, 0.28],
          ],
          0.028,
          0.004,
        ),
      ),
      M.krakenRidge,
    );
    add(
      head,
      cached(`kraken_horn_inner_${side}`, () =>
        tendril(
          [
            [side * 0.03, 0.15, 0.05],
            [side * 0.045, 0.235, 0.12],
            [side * 0.05, 0.28, 0.22],
          ],
          0.022,
          0.003,
        ),
      ),
      M.krakenRidge,
    );
  }
  // 头胸表面的疣粒与鹦鹉喙。
  const warts = [
    [0.0, 0.19, 0.16, 0.035],
    [-0.09, 0.16, 0.24, 0.028],
    [0.1, 0.15, 0.28, 0.024],
    [-0.05, 0.18, 0.34, 0.02],
    [0.06, 0.17, 0.38, 0.016],
  ];
  for (const [x, y, z, size] of warts)
    blob(head, M.krakenRidge, [x, y, z], [size, size * 0.7, size], true);
  blob(head, M.black, [0, -0.085, -0.075], [0.055, 0.045, 0.038]);
  spike(head, M.krakenRidge, [0, -0.06, -0.09], [0, -0.4, -1], 0.022, 0.055);
  for (let index = 0; index < 8; index++) {
    const angle = (index / 8) * Math.PI * 2 + Math.PI / 8;
    const c = Math.cos(angle),
      s = Math.sin(angle);
    // 上方两条腕扬得更高，形成扑击姿态。
    const lift = s > 0.3 ? 0.08 : 0;
    const arm = new THREE.Group();
    arm.position.set(c * 0.11, s * 0.095 - 0.01, -0.04);
    inner.add(arm);
    const points = [
      [0, 0, 0],
      [c * 0.2, s * 0.18 + lift * 0.4, -0.14],
      [c * 0.32, s * 0.27 + lift, -0.28],
      [c * 0.42, s * 0.33 + lift, -0.4],
      [c * 0.46, s * 0.35 + lift, -0.3],
      [c * 0.44, s * 0.36 + lift * 0.8, -0.14],
    ];
    add(
      arm,
      cached(`kraken_arm_${index}`, () => tendril(points, 0.048, 0.003)),
      M.kraken,
    );
    const curve = curveFrom(points);
    for (let j = 1; j < 9; j++) {
      const p = curve.getPoint(j / 10.5);
      const size = 0.017 * (1 - j / 13);
      blob(
        arm,
        M.krakenSucker,
        [p.x - c * 0.026, p.y - s * 0.026 - 0.006, p.z + 0.004],
        [size, size * 0.55, size],
      );
    }
    motions.push((t, effort) => {
      // 缓慢挥舞；高速移动时略微收拢减阻。
      const amp = 1.15 - effort * 0.25;
      arm.rotation.z = Math.sin(t * 0.3 + angle) * 0.14 * amp;
      arm.rotation.x = Math.cos(t * 0.26 + angle) * 0.1 * amp;
      arm.rotation.y = Math.sin(t * 0.24 + angle * 1.4) * 0.1 * amp;
    });
  }
  motions.push((t) => {
    head.scale.setScalar(1 + Math.sin(t * 0.45) * 0.018);
    inner.rotation.z = Math.sin(t * 0.2) * 0.025;
  });
}

function buildDunkleosteus(root, motions) {
  const inner = new THREE.Group();
  root.add(inner);
  // 厚重骨甲头盾占据前半身，后半身裸露渐细。
  add(
    inner,
    cached("dunkleosteus_rear", () =>
      formColored(
        [
          [-0.12, 0.152, 0.156],
          [0.05, 0.128, 0.13],
          [0.2, 0.07, 0.08],
          [0.33, 0.028, 0.038],
          [0.4, 0.01, 0.016],
        ],
        "#2c3941",
        "#4d5a55",
      ),
    ),
    M.body,
  );
  add(
    inner,
    cached("dunkleosteus_shield", () =>
      formColored(
        [
          [-0.46, 0.1, 0.09],
          [-0.38, 0.165, 0.156],
          [-0.24, 0.185, 0.176],
          [-0.09, 0.163, 0.158],
        ],
        "#38474a",
        "#4d5a55",
      ),
    ),
    M.body,
  );
  const forehead = blob(
    inner,
    M.armor,
    [0, 0.1, -0.26],
    [0.16, 0.1, 0.18],
    true,
  );
  forehead.rotation.x = -0.08;
  blob(inner, M.armor, [0, 0.03, -0.425], [0.095, 0.07, 0.07], true);
